CREATE TABLE public.crm_schedule_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid NOT NULL REFERENCES public.crm_schedules(id), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), owner_id uuid NOT NULL, department_id uuid, attributed_at timestamptz NOT NULL, data jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crm_schedule_history TO authenticated; GRANT ALL ON public.crm_schedule_history TO service_role;
ALTER TABLE public.crm_schedule_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_schedule_history_read ON public.crm_schedule_history FOR SELECT TO authenticated USING(crm_customer_visible(customer_id) AND crm_owner_visible(owner_id,department_id,attributed_at));
CREATE FUNCTION private.crm_schedule_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO crm_schedule_history(schedule_id,customer_id,owner_id,department_id,attributed_at,data) VALUES(NEW.id,NEW.customer_id,NEW.owner_id,NEW.department_id,NEW.attributed_at,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER crm_schedule_snapshot AFTER INSERT OR UPDATE ON public.crm_schedules FOR EACH ROW EXECUTE FUNCTION private.crm_schedule_snapshot();
INSERT INTO public.crm_schedule_history(schedule_id,customer_id,owner_id,department_id,attributed_at,data,recorded_at) SELECT id,customer_id,owner_id,department_id,attributed_at,to_jsonb(s),created_at FROM public.crm_schedules s;
CREATE OR REPLACE FUNCTION private.crm_event_visible(_customer uuid,_schedule uuid,_before jsonb,_after jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; dept uuid; at_ timestamptz; BEGIN IF _customer IS NULL THEN RETURN crm_can(auth.uid(),'biz.crm_settings'); END IF; IF NOT crm_customer_visible(_customer) THEN RETURN false; END IF; owner:=coalesce(nullif(_before->>'owner_id','')::uuid,nullif(_after->>'owner_id','')::uuid,(SELECT owner_id FROM crm_schedules WHERE id=_schedule),(SELECT owner_id FROM crm_customers WHERE id=_customer)); dept:=coalesce(nullif(_before->>'department_id','')::uuid,nullif(_after->>'department_id','')::uuid); at_:=coalesce(nullif(_before->>'attributed_at','')::timestamptz,nullif(_after->>'attributed_at','')::timestamptz,now()); RETURN crm_owner_visible(owner,dept,at_); END $$;
ALTER POLICY crm_event_read ON public.crm_events USING(private.crm_event_visible(customer_id,schedule_id,before_data,after_data));
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.crm_detail(uuid)'::regprocedure) INTO d; d:=replace(d,'FROM crm_events e WHERE customer_id=_id','FROM crm_events e WHERE customer_id=_id AND private.crm_event_visible(e.customer_id,e.schedule_id,e.before_data,e.after_data)'); EXECUTE d; SELECT pg_get_functiondef('public.crm_report(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid)'::regprocedure) INTO d; d:=replace(d,'FROM crm_schedules s WHERE s.customer_id IN','FROM (SELECT DISTINCT ON (h.schedule_id) (jsonb_populate_record(NULL::public.crm_schedules,h.data)).* FROM public.crm_schedule_history h WHERE h.recorded_at<hi ORDER BY h.schedule_id,h.recorded_at DESC,h.id DESC) s WHERE s.customer_id IN'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.crm_export(_start date,_end date,_mine boolean DEFAULT true,_owner uuid DEFAULT NULL,_group uuid DEFAULT NULL,_province text DEFAULT NULL,_department uuid DEFAULT NULL,_system uuid DEFAULT NULL,_team uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_can(auth.uid(),'biz.crm_export') THEN RAISE EXCEPTION 'Bạn không có quyền xuất CRM.'; END IF; RETURN crm_report(_start,_end,_mine,_owner,_group,_province,_department,_system,_team); END $$;
CREATE OR REPLACE FUNCTION public.crm_remind() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result int:=0; r record; BEGIN FOR r IN SELECT s.owner_id,count(*) total FROM crm_schedules s JOIN crm_customers c ON c.id=s.customer_id WHERE s.status='pending' AND c.archived_at IS NULL AND s.due_at-make_interval(days=>s.reminder_days)<now() AND crm_can(s.owner_id,'biz.crm_use') GROUP BY s.owner_id LOOP INSERT INTO notifications(recipient_id,kind,dedup_key,payload,zalo_status,push_status) VALUES(r.owner_id,'biz_deadline','crm:care:'||r.owner_id||':'||(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date,jsonb_build_object('module','crm','message','CRM: '||r.total||' lịch chăm sóc đang đến hạn hoặc quá hạn.'),'ineligible','none') ON CONFLICT(dedup_key) DO NOTHING; IF FOUND THEN result:=result+1; END IF; END LOOP; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.crm_remind() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.crm_remind() TO service_role;
REVOKE ALL ON FUNCTION public.crm_export(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_export(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION private.crm_schedule_snapshot() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION private.crm_event_visible(uuid,uuid,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.crm_event_visible(uuid,uuid,jsonb,jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION private.crm_rules_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='crm_schedules' THEN IF NEW.kind<>ALL(ARRAY['appointment','recurring','seasonal']) OR NEW.status<>ALL(ARRAY['pending','processed','paused']) OR (NEW.kind='recurring' AND (NEW.interval_days IS NULL OR NEW.interval_days<1 OR NEW.interval_days>3660)) OR (NEW.fixed_weekday IS NOT NULL AND (NEW.fixed_weekday<0 OR NEW.fixed_weekday>6)) THEN RAISE EXCEPTION 'Loại lịch, trạng thái hoặc chu kỳ không hợp lệ.'; END IF; ELSIF TG_TABLE_NAME='crm_interactions' THEN IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Lịch sử chăm sóc chính thức không được ghi đè hoặc xóa.'; END IF; ELSIF TG_TABLE_NAME='crm_catalogs' THEN IF NEW.kind='outcome' AND coalesce((NEW.config->>'completed')::boolean,false) AND NOT coalesce((NEW.config->>'connected')::boolean,false) THEN RAISE EXCEPTION 'Chưa kết nối không thể là hoàn tất hợp lệ.'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_schedule_rules BEFORE INSERT OR UPDATE ON public.crm_schedules FOR EACH ROW EXECUTE FUNCTION private.crm_rules_guard();
CREATE TRIGGER crm_interaction_immutable BEFORE UPDATE OR DELETE ON public.crm_interactions FOR EACH ROW EXECUTE FUNCTION private.crm_rules_guard();
CREATE TRIGGER crm_outcome_rules BEFORE INSERT OR UPDATE ON public.crm_catalogs FOR EACH ROW EXECUTE FUNCTION private.crm_rules_guard();
REVOKE ALL ON FUNCTION private.crm_rules_guard() FROM PUBLIC,anon,authenticated;